OUT=Path(__file__).parent/'dist'
ORIGIN='https://thesnippitypip.co.uk'
BOOK='https://bookings.gettimely.com/thesnippitypip/bb/book'

def button(label,url,style='',external=False):
    attrs=' target="_blank" rel="noopener noreferrer"' if external else ''
    return f'<a class="btn {style}" href="{url}"{attrs}>{label}<span class="arrow" aria-hidden="true"><img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></span></a>'

def link(label,url):return f'<a class="text-link" href="{url}">{label}<span aria-hidden="true"><img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></span></a>'
def art():return '<div class="academy-art"><img src="/assets/academy-logo-transparent.webp" alt="The Snippitypip Training Academy sunflower and scissors logo" loading="lazy"></div>'
def crumb(label):return f'<div class="breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>{label}</span></div>'
def pagehero(label,title,text):return f'<div class="wrap"><div class="page-hero">{crumb(label)}<span class="eyebrow">{label}</span><h1>{title}</h1><p class="lead">{text}</p></div></div>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def cta():return f'<section class="soft cta"><span class="eyebrow">Your next chapter starts here</span><h2>A new look. A new skill.<br><em>A little more you.</em></h2><p>Make time for yourself, or make room for something new. We’d love to be part of it.</p><div class="actions">{button("Book a hair appointment",BOOK,external=True)}{link("Explore the academy","/academy.html")}</div></section>'
def brand():return '<a class="brand" href="/" aria-label="The Snippitypip home"><img src="/assets/salon-logo-transparent.webp" width="69" height="69" alt=""><span class="wordmark"><strong>The Snippitypip</strong><small>Hair stylist & training academy</small></span></a>'

def render(name,title,description,content,extra_js=''):
    links=[('salon.html','The salon'),('academy.html','The academy'),('shop.html','Online Store'),('about.html','Meet Pippin'),('contact.html','Get in touch') ]
    nav=''.join(f'<a href="/{path}"'+(' aria-current="page"' if name==path or (name=='classroom.html' and path=='academy.html') or (path=='salon.html' and name in [item['slug']+'.html' for item in SERVICES]+['haircare.html']) else '')+f'>{label}</a>' for path,label in links)
    canonical=ORIGIN+('/' if name=='index.html' else '/'+name)
    html=f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | The Snippitypip</title><meta name="description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#173f35"><meta name="robots" content="noindex,nofollow"><meta property="og:title" content="{escape(title,quote=True)} | The Snippitypip"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:image" content="{ORIGIN}/assets/salon-hero.jpg"><meta property="og:url" content="{canonical}"><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/salon-logo-transparent.webp"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/portal.css"><script src="/main.js" defer></script>{extra_js}</head>
<body><a class="skip-link" href="#main">Skip to content</a><div class="topbar"><div class="wrap"><span>Saltash, Cornwall</span><span class="topbar-center">A little creativity. A lot of confidence.</span><span>Academy courses coming soon</span></div></div>
<header class="site-header"><div class="wrap nav">{brand()}<nav id="navigation" class="navlinks" aria-label="Main navigation">{nav}</nav>{button('Book an appointment',BOOK,external=True)}<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">☰</button></div></header>
<main id="main">{content}</main>
<footer class="footer"><div class="wrap"><div class="footer-main"><div>{brand()}<p class="footer-intro">Personal hairdressing. Thoughtful education. Helping you feel confident in your own next chapter.</p></div><div><h4>Explore</h4><div class="footer-links"><a href="/shop.html">Online Store · Coming Soon</a><a href="/salon.html">Hair services</a><a href="/salon.html#bridal">Bridal &amp; occasion hair</a><a href="/salon.html#customer-links">Hair customer links</a><a href="/academy.html">Training academy</a><a href="/about.html">Meet Pippin</a><a href="/contact.html">Get in touch</a></div></div><div><h4>Your next step</h4><div class="footer-links"><a href="{BOOK}" target="_blank" rel="noopener noreferrer">Book an appointment <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a><a href="/contact.html?interest=Training%20academy">Training enquiries</a><a href="/privacy.html">Privacy & cookies</a></div></div><div><h4>Let’s connect</h4><div class="footer-links"><a class="email" href="mailto:thesnippitypip@hotmail.com">thesnippitypip@hotmail.com</a><span>Saltash, Cornwall</span><div class="socials"><a href="https://www.instagram.com/thesnippitypip/" target="_blank" rel="noopener noreferrer">Instagram <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a><a href="https://www.facebook.com/p/Thesnippitypip-100064112289747/" target="_blank" rel="noopener noreferrer">Facebook <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a><a href="https://www.tiktok.com/@thesnippitypip" target="_blank" rel="noopener noreferrer">TikTok <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a></div></div></div></div><div class="footer-bottom"><span>© 2026 The Snippitypip. All rights reserved.</span><span>Hair artistry & education, with a personal touch.</span></div></div></footer></body></html>'''
    (OUT/name).write_text(html)

